import React, { ReactElement } from 'react';

import { Menu } from '../../../../../navigation/menu/Menu.js';
import { Group } from '../components/Group.js';
import { Item } from '../components/Item.js';
import { ItemIcon } from '../components/ItemIcon.js';
import { ItemTooltip } from '../components/ItemTooltip.js';
import { Label } from '../components/Label.js';

/**
 * Wraps the passed child element in the corresponding Menu component
 * or calls the function recursively if the child is a Group
 *
 * @param child - element to render
 */
export function renderMenuActionChildren(
  child: ReactElement,
): ReactElement | undefined {
  if (!child) {
    return;
  }
  switch (child.type) {
    case Item:
      return (
        <Menu.Item
          onSelect={child.props.onSelect}
          disabled={child.props.disabled}
        >
          {React.Children.map(
            child?.props?.children,
            (itemChild: ReactElement) => {
              if (itemChild?.type === ItemTooltip) {
                return <Menu.ItemTooltip>{itemChild}</Menu.ItemTooltip>;
              } else if (itemChild?.type === ItemIcon) {
                return <Menu.ItemIcon>{itemChild}</Menu.ItemIcon>;
              }

              return itemChild;
            },
          )}
        </Menu.Item>
      );
    case Label:
      return <Menu.Label>{child}</Menu.Label>;
    case Group:
      return (
        <Menu.Group>
          {React.Children.map(
            child?.props?.children,
            (itemChild: ReactElement) => renderMenuActionChildren(itemChild),
          )}
        </Menu.Group>
      );
    default:
      return;
  }
}
